// Cortina de abertura feita com um trecho real do tecido do auditório.
// O tecido vai embutido neste arquivo para funcionar também abrindo o site direto
// do disco. A cor vem de TECIDO.tons, medida na foto. "Pular abertura", movimento
// reduzido e limpeza do canvas são integrações do site.
(() => {
  // Ajustes da cortina
  const CONFIG = {
    duracao: 3.8,   // segundos que as cortinas levam para abrir
    pausa: 0.7,     // segundos fechadas antes de começar a abrir
  };

  /* A cortina usa um trecho do tecido real do auditório. O tecido é comprimido
     em tempo real na abertura, e a costura central é a abertura real da cortina. */
  const TECIDO = {"foto": "data:image/jpeg;base64,", "costura": 0.3635693215339233, "tons": [[0, 30, 30, 42], [30, 31, 29, 33], [45, 47, 45, 51], [60, 61, 59, 67], [75, 76, 73, 82], [90, 91, 89, 96], [105, 107, 103, 108], [120, 122, 119, 122], [135, 138, 134, 135], [150, 153, 149, 150], [165, 168, 164, 163], [180, 182, 178, 177], [195, 196, 191, 188], [260, 232, 228, 222], [320, 246, 243, 238]]};

  const canvas = document.getElementById('cortina');
  const body = document.body;
  const opening = document.getElementById('opening-curtains');
  if (!canvas || !opening) return;
  const motionPreference = matchMedia('(prefers-reduced-motion: reduce)');
  let finished = false;
  let frameId = 0;
  let safetyTimeout;

  function finishOpening() {
    if (finished) return;
    finished = true;
    const restoreFocus = opening.contains(document.activeElement);
    cancelAnimationFrame(frameId);
    clearTimeout(safetyTimeout);
    removeEventListener('resize', onResize);
    motionPreference.removeEventListener('change', onMotionChange);
    opening.remove();
    document.documentElement.classList.remove('has-opening');
    body.classList.remove('curtain-opening');
    if (restoreFocus) document.querySelector('.site-header .brand')?.focus({ preventScroll: true });
  }
  function onMotionChange(event) {
    if (event.matches) finishOpening();
  }
  function onResize() {
    if (!finished && niveis.length && (innerWidth !== cssW || innerHeight !== cssH)) {
      configura();
      desenha(0);
    }
  }
  opening.querySelector('.curtain-skip').addEventListener('click', finishOpening);

  // Quem pediu ao sistema menos animação entra direto no site
  if (motionPreference.matches) {
    finishOpening();
    return;
  }
  document.documentElement.classList.add('has-opening');
  body.classList.add('curtain-opening');
  motionPreference.addEventListener('change', onMotionChange);
  safetyTimeout = setTimeout(finishOpening, (CONFIG.pausa + CONFIG.duracao + 3) * 1000);

  const ctx = canvas.getContext('2d');
  if (!ctx) {
    finishOpening();
    return;
  }

  const N_U = 4096, N_X = 2048, LIMITE_PIXELS = 1.5e6;

  const lerp = (a, b, t) => a + (b - a) * t;
  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
  const suave = (a, b, v) => {
    const t = clamp((v - a) / (b - a), 0, 1);
    return t * t * (3 - 2 * t);
  };
  const movimento = (t) => t * t * t * (t * (t * 6 - 15) + 10);

  function aleatorio(semente) {
    let s = semente >>> 0;
    return () => {
      s = (s + 0x6D2B79F5) >>> 0;
      let z = Math.imul(s ^ (s >>> 15), 1 | s);
      z = (z + Math.imul(z ^ (z >>> 7), 61 | z)) ^ z;
      return ((z ^ (z >>> 14)) >>> 0) / 4294967296;
    };
  }

  /* Paleta: de cada tom de cinza para a cor real medida no tecido */
  const TONS = 320;                 // cinza até 319, para o tecido poder clarear um pouco
  const PALETA = new Uint32Array(TONS);
  {
    const p = TECIDO.tons;
    for (let i = 0; i < TONS; i++) {
      let j = 0;
      while (j < p.length - 2 && i > p[j + 1][0]) j++;
      const a = p[j], b = p[j + 1], t = (i - a[0]) / (b[0] - a[0]);
      const c = (n) => clamp(Math.round(lerp(a[n], b[n], t)), 0, 255);
      PALETA[i] = ((255 << 24) | (c(3) << 16) | (c(2) << 8) | c(1)) >>> 0;
    }
  }

  /* Níveis do tecido, cada um com metade da largura, para não tremer quando comprimido */
  let niveis = [], texW = 0, texH = 0;

  function preparaTecido(img) {
    const c = document.createElement('canvas');
    c.width = texW = img.width;
    c.height = texH = img.height;
    const x = c.getContext('2d', { willReadFrequently: true });
    x.drawImage(img, 0, 0);
    const d = x.getImageData(0, 0, texW, texH).data;
    const base = new Uint8Array(texW * texH);
    for (let i = 0; i < base.length; i++) base[i] = d[i * 4];
    niveis = [base];
    let w = texW;
    for (let n = 1; n < 5; n++) {
      const a = niveis[n - 1], nw = w >> 1, b = new Uint8Array(nw * texH);
      for (let y = 0; y < texH; y++) {
        const l = y * w, m = y * nw;
        for (let i = 0; i < nw; i++) b[m + i] = (a[l + i * 2] + a[l + i * 2 + 1] + 1) >> 1;
      }
      niveis.push(b);
      w = nw;
    }
  }

  function criaOndas(semente) {
    const rand = aleatorio(semente);
    const ondas = [0, 1, 2].map((i) => ({ f: 3.3 * (1 + i * .7) * (.85 + rand() * .3), p: rand() * 6.283, a: 1 / (1 + i) }));
    const curva = new Float32Array(N_U);
    for (let i = 0; i < N_U; i++) {
      const u = i / (N_U - 1);
      curva[i] = ondas.reduce((t, o) => t + o.a * Math.sin(u * o.f * 6.283 + o.p), 0) / 1.8;
    }
    return { curva, semente: rand() * 10 };
  }

  let W, H, buf, img, panos, bandoLarg, sombraLarg, colLuz, linLuz, linAtraso;
  let qualidade = 1, cssW = 0, cssH = 0, spanTex = 0;
  const xDoU = [new Int32Array(N_U), new Int32Array(N_U)];

  const uDoX = new Int32Array(N_X);
  const compressao = new Float32Array(N_X);
  const bordaLuz = new Float32Array(N_X);
  for (let i = 0; i < N_X; i++) bordaLuz[i] = 1 - 0.18 * suave(0.988, 1, i / (N_X - 1));

  function configura() {
    cssW = innerWidth;
    cssH = innerHeight;
    const dpr = Math.min(devicePixelRatio || 1, 2);
    const escala = Math.min(dpr, Math.sqrt(LIMITE_PIXELS / (cssW * cssH))) * qualidade;

    W = Math.max(2, Math.round(cssW * escala));
    H = Math.max(2, Math.round(cssH * escala));
    canvas.width = W;
    canvas.height = H;
    img = ctx.createImageData(W, H);
    buf = new Uint32Array(img.data.buffer);

    panos = [criaOndas(11), criaOndas(37)];
    bandoLarg = Math.max(W * 0.085, 60 * escala);
    sombraLarg = Math.max(18, W * 0.05);

    // Quanto do tecido cabe em cada lado, mantendo a proporção das pregas
    const costura = TECIDO.costura * texW;
    const deseja = (cssW / 2 / cssH) * texH * 1.12;
    spanTex = Math.min(deseja, costura - 2, texW - costura - 2);
    for (let i = 0; i < N_U; i++) {
      const r = 1 - i / (N_U - 1);
      xDoU[0][i] = (costura - r * spanTex) | 0;
      xDoU[1][i] = (costura + r * spanTex) | 0;
    }

    colLuz = new Float32Array(W).fill(1);
    linLuz = new Float32Array(H);
    linAtraso = new Float32Array(H);
    for (let y = 0; y < H; y++) {
      const yn = y / (H - 1);
      linLuz[y] = (0.93 + 0.1 * suave(0, 0.25, yn)) * (1 - 0.14 * suave(0.9, 1, yn));
      linAtraso[y] = 0.32 * Math.pow(yn, 1.7);
    }
  }

  function escurece(i, a) {
    const d = buf[i], da = d >>> 24;
    if (da === 255) {
      const f = 1 - a;
      buf[i] = ((255 << 24) | (((d >> 16) & 255) * f << 16) | (((d >> 8) & 255) * f << 8) | ((d & 255) * f)) >>> 0;
    } else {
      const fundo = (da / 255) * (1 - a), alfa = a + fundo, f = alfa > 0 ? fundo / alfa : 0;
      buf[i] = (((alfa * 255) << 24) | (((d >> 16) & 255) * f << 16) | (((d >> 8) & 255) * f << 8) | ((d & 255) * f)) >>> 0;
    }
  }

  function bordaSuave(i, cor, a) {
    const d = buf[i];
    if (d >>> 24 === 255) {
      const f = 1 - a;
      const r = (d & 255) * f + (cor & 255) * a;
      const g = ((d >> 8) & 255) * f + ((cor >> 8) & 255) * a;
      const b = ((d >> 16) & 255) * f + ((cor >> 16) & 255) * a;
      buf[i] = ((255 << 24) | (b << 16) | (g << 8) | r) >>> 0;
    } else {
      buf[i] = (((a * 255) << 24) | (cor & 0xffffff)) >>> 0;
    }
  }

  function preparaCompressao(e, rapidez, t) {
    // Enquanto é puxado, o tecido se acumula perto da borda que está andando
    const gama = 1 + 0.42 * Math.sin(Math.PI * e);
    const ondula = rapidez * 0.012;
    let anterior = 0;
    for (let i = 0; i < N_X; i++) {
      const n = i / (N_X - 1);
      let u = Math.pow(n, gama);
      u += ondula * Math.sin(Math.PI * 2 * (3 * u - 2.2 * t)) * n * (1 - n) * 4;
      u = clamp(u, 0, 1);
      uDoX[i] = (u * (N_U - 1)) | 0;
      compressao[i] = i === 0 ? 0.4 : Math.max(0.4, (u - anterior) * (N_X - 1));
      anterior = u;
    }
    compressao[0] = compressao[1];
  }

  function desenhaLado(lado, t, tAbrir, rapidez) {
    const { curva, semente } = panos[lado];
    const xU = xDoU[lado];
    const espelho = lado === 1;
    const dur = CONFIG.duracao;
    const metade = W * 0.5;

    for (let y = 0; y < H; y++) {
      const yn = y / (H - 1);
      const linha = y * W;

      const tempo = clamp((tAbrir - linAtraso[y] - (espelho ? 0.05 : 0)) / dur, 0, 1);
      const e = movimento(tempo);
      const largBase = lerp(metade, bandoLarg, e);
      const fora = -(bandoLarg + sombraLarg + 6) * suave(0.62, 1, e);

      const tremor = W * (0.0012 * e + 0.005 * rapidez) * yn * yn * Math.sin(yn * 5 + t * 1.3 + semente);
      const larg = largBase + tremor;
      const borda = fora + larg;

      const sombra = sombraLarg * lerp(0.06, 1, suave(0, 0.14, e));
      if (borda <= -sombra) continue;

      const passo = (N_X - 1) / larg;
      const x1 = Math.min(W, Math.floor(borda));
      let xF = -fora * passo;

      for (let x = Math.max(0, x1), fim = Math.min(W, borda + sombra); x < fim; x++) {
        const d = Math.min(1, 1 - (x - borda) / sombra);
        escurece(linha + (espelho ? W - 1 - x : x), d * d * 0.5);
      }

      const aU = N_U * yn * yn * (rapidez * 0.022 * Math.sin(t * 5 - yn * 5 + semente) +
        e * (0.012 + 0.004 * Math.sin(t * .8 + yn * 2 + semente)));
      const luzLinha = linLuz[y];
      const yTex = (yn * (texH - 1)) | 0;
      const escalaLinha = spanTex / larg;   // texels do tecido por pixel, sem compressão

      let cor = 0;
      for (let x = 0; x < x1; x++) {
        const xn = xF | 0;
        xF += passo;

        const u0 = uDoX[xn];
        let u = u0 + ((curva[u0] * aU) | 0);
        if (u < 0) u = 0; else if (u >= N_U) u = N_U - 1;

        // Nível do tecido conforme a compressão, e sombra extra no tecido amontoado
        const comp = compressao[xn] * escalaLinha;
        const nv = comp < 1.5 ? 0 : comp < 3 ? 1 : comp < 6 ? 2 : comp < 12 ? 3 : 4;
        const cinza = niveis[nv][yTex * (texW >> nv) + (xU[u] >> nv)];
        const junta = comp < 1.2 ? 1 : 1 - 0.3 * suave(1.2, 6, comp);

        let p = (cinza * luzLinha * bordaLuz[xn] * junta) | 0;
        if (p >= TONS) p = TONS - 1;
        cor = PALETA[p];
        buf[linha + (espelho ? W - 1 - x : x)] = cor;
      }

      if (x1 >= 0 && x1 < W) {
        const a = borda - x1;
        if (a > 0.004) bordaSuave(linha + (espelho ? W - 1 - x1 : x1), cor, a);
      }
    }
  }

  function desenha(t) {
    const tAbrir = t - CONFIG.pausa;
    const prog = clamp(tAbrir / CONFIG.duracao, 0, 1);
    const rapidez = 16 * prog * prog * (1 - prog) * (1 - prog);
    buf.fill(0);
    preparaCompressao(movimento(prog), rapidez, t);
    desenhaLado(0, t, tAbrir, rapidez);
    desenhaLado(1, t, tAbrir, rapidez);
    ctx.putImageData(img, 0, 0);
    return movimento(prog);
  }

  const foto = new Image();
  foto.onerror = finishOpening;
  foto.onload = () => {
    if (finished) return;
    preparaTecido(foto);
    configura();
    desenha(0);

    // Mede o aparelho e reduz a resolução se ele for lento
    const medir = () => {
      let ms = 0;
      for (let n = 0; n < 3; n++) {
        const a = performance.now();
        desenha(0);
        ms = performance.now() - a;
      }
      return ms;
    };
    if (medir() > 13) {
      qualidade = 0.72;
      configura();
      if (medir() > 13) {
        qualidade = 0.5;
        configura();
      }
      desenha(0);
    }
    canvas.style.background = 'transparent';
    addEventListener('resize', onResize);

    const fim = CONFIG.pausa + CONFIG.duracao + 0.5;
    let comeco = 0;
    const quadro = (agora) => {
      if (finished) return;
      if (!comeco) comeco = agora;
      const t = (agora - comeco) / 1000;
      if (t >= fim) {
        finishOpening();
        return;
      }
      desenha(t);
      frameId = requestAnimationFrame(quadro);
    };
    frameId = requestAnimationFrame(quadro);
  };
  foto.src = TECIDO.foto;
})();
